    out.insert("comment".into(), json!(mf.comment));
    out.insert("lyrics".into(), json!(mf.lyrics));
    out.insert("explicitStatus".into(), json!(mf.explicit_status));
    out.insert("year".into(), json!(mf.year));
    out.insert("date".into(), json!(mf.date));
    out.insert("originalYear".into(), json!(mf.original_year));
    out.insert("originalDate".into(), json!(mf.original_date));
    out.insert("releaseYear".into(), json!(mf.release_year));
    out.insert("releaseDate".into(), json!(mf.release_date));
    out.insert("mbzRecordingId".into(), json!(mf.mbz_recording_id));
    out.insert("mbzReleaseTrackId".into(), json!(mf.mbz_release_track_id));
    out.insert("mbzAlbumId".into(), json!(mf.mbz_album_id));
    out.insert("mbzReleaseGroupId".into(), json!(mf.mbz_release_group_id));
    out.insert("mbzAlbumType".into(), json!(mf.mbz_album_type));
    out.insert("hasCoverArt".into(), json!(mf.has_cover_art));
    out.insert("duration".into(), json!(mf.duration as f64));
    out.insert("bitRate".into(), json!(mf.bit_rate));
    out.insert("sampleRate".into(), json!(mf.sample_rate));
    out.insert("channels".into(), json!(mf.channels));
    out.insert("codec".into(), json!(mf.codec));
    out.insert("path".into(), json!(mf.path));
    out.insert("suffix".into(), json!(mf.suffix));
    out.insert("size".into(), json!(mf.size));
    out.insert("artist".into(), json!(mf.artist));
    out.insert("albumArtist".into(), json!(mf.album_artist));
    out.insert("artistId".into(), json!(mf.artist_id));
    out.insert("albumArtistId".into(), json!(mf.album_artist_id));
    out.insert("orderArtistName".into(), json!(mf.order_artist_name));
    out.insert(
        "orderAlbumArtistName".into(),
        json!(mf.order_album_artist_name),
    );
    out.insert("sortArtistName".into(), json!(mf.sort_artist_name));
    out.insert(
        "sortAlbumArtistName".into(),
        json!(mf.sort_album_artist_name),
    );
    out.insert("bpm".into(), json!(mf.bpm));
    out.insert("bitDepth".into(), json!(mf.bit_depth));
    out.insert("rgAlbumPeak".into(), json!(mf.rg_album_peak));
    out.insert("rgAlbumGain".into(), json!(mf.rg_album_gain));
